define('taoQtiItem/qtiCreator/editor/interactionsPanel',['taoQtiItem/qtiCreator/editor/interactionsToolbar', 'taoQtiItem/qtiCreator/helper/panel', 'taoQtiItem/qtiCreator/helper/qtiElements', 'taoQtiItem/portableElementRegistry/ciRegistry', 'services/features'], function (interactionsToolbar, panel, qtiElements, ciRegistry, features) {
  'use strict';
  return function setUpInteractionPanel($container) {
    var interactions = qtiElements.getAvailableAuthoringElements();
    var liquidsInteractionAvailable = features.isVisible('taoQtiItem/creator/interaction/pci/liquidsInteraction');
    var liquidsInteractionId = 'liquidsInteraction';
    for (var typeId in ciRegistry.getAllVersions()) {
      if (typeId === liquidsInteractionId && !liquidsInteractionAvailable) continue;
      var data = ciRegistry.getAuthoringData(typeId, {
        enabledOnly: true
      });
      if (data && data.tags && data.tags[0] === interactionsToolbar.getCustomInteractionTag()) {
        interactions[data.qtiClass] = data;
      }
    }
    interactionsToolbar.create($container, interactions);
    panel.initSidebarAccordion($container);
    panel.closeSections($container.find('section'));
    panel.openSections($container.find('#sidebar-left-section-common-interactions'), false);
    panel.toggleInlineInteractionGroup();
  };
});
