define('taoQtiItem/qtiCreator/plugins/content/changeTracker',['core/plugin', 'taoQtiItem/qtiCreator/helper/changeTracker'], function (pluginFactory, changeTrackerFactory) {
  'use strict';
  return pluginFactory({
    name: 'changeTracker',
    init() {
      var itemCreator = this.getHost();
      var $container = this.getAreaBroker().getContainer();
      this.changeTracker = changeTrackerFactory($container.get(0), itemCreator, '.content-wrap');
    },
    destroy() {
      if (this.changeTracker) {
        this.changeTracker.uninstall();
        this.changeTracker = null;
      }
    }
  });
});
