define('taoQtiItem/qtiCreator/widgets/interactions/states/Sleep',['taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Sleep'], function (stateFactory, SleepState) {
  var InteractionStateSleep = stateFactory.extend(SleepState, function () {
    var _widget = this.widget;
    _widget.$container.on('click.qti-widget.sleep', function (e) {
      e.stopPropagation();
      _widget.changeState('question');
    });
  }, function () {
    var _widget = this.widget;
    _widget.$container.off('.sleep');
  });
  return InteractionStateSleep;
});
