define('taoQtiItem/qtiCreator/model/interactions/HotspotInteraction',['jquery', 'lodash', 'taoQtiItem/qtiCreator/model/mixin/editable', 'taoQtiItem/qtiCreator/model/mixin/editableInteraction', 'taoQtiItem/qtiItem/core/interactions/HotspotInteraction', 'taoQtiItem/qtiCreator/model/choices/HotspotChoice'], function ($, _, editable, editableInteraction, Interaction, Choice) {
  "use strict";

  var methods = {};
  _.extend(methods, editable);
  _.extend(methods, editableInteraction);
  _.extend(methods, {
    getDefaultAttributes: function getDefaultAttributes() {
      return {
        'maxChoices': 0,
        'minChoices': 0
      };
    },
    afterCreate: function afterCreate() {
      var relatedItem = this.getRootElement();
      var isResponsive = relatedItem.data('responsive');
      if (isResponsive === true) {
        this.addClass('responsive');
      }
      this.createResponse({
        baseType: 'identifier',
        cardinality: 'single'
      });
    },
    createChoice: function createChoice(attr) {
      var choice = new Choice('', attr);
      this.addChoice(choice);
      choice.buildIdentifier('hotspot');
      if (this.getRenderer()) {
        choice.setRenderer(this.getRenderer());
      }
      $(document).trigger('choiceCreated.qti-widget', {
        'choice': choice,
        'interaction': this
      });
      return choice;
    }
  });
  return Interaction.extend(methods);
});
