define('taoQtiItem/qtiCreator/widgets/interactions/inlineInteraction/Widget',['taoQtiItem/qtiCreator/widgets/interactions/Widget'], function (Widget) {
  var InlineInteractionWidget = Widget.clone();
  InlineInteractionWidget.destroy = function () {
    this.$original.off('.qti-widget');
    this.$container.remove();
    this.offEvents();
  };
  return InlineInteractionWidget;
});
