define('taoQtiItem/qtiCreator/widgets/interactions/textEntryInteraction/states/Correct',['jquery', 'i18n', 'taoQtiItem/qtiCreator/widgets/helpers/stringResponse', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Correct', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'util/locale', 'util/converter'], function ($, __, stringResponseHelper, stateFactory, Correct, instructionMgr, locale, converter) {
  'use strict';

  function setErrorNotification(submitButton, element, baseType) {
    submitButton.attr('disabled', true);
    instructionMgr.appendInstruction(element, __('This is not a valid value. Expected %s', baseType));
  }
  function start() {
    var widget = this.widget;
    var element = widget.element;
    var $container = widget.$container;
    var $responseForm = widget.$responseForm;
    var $submitButton = $container.find('button.widget-ok');
    var $correctInput = $container.find('tr[data-edit=correct] input[name=correct]');
    var response = element.getResponseDeclaration();
    var attributes = response.attributes;
    var decimalSeparator = locale.getDecimalSeparator();
    var correctResponse = stringResponseHelper.getCorrectResponse(response);
    instructionMgr.removeInstructions(element);
    instructionMgr.appendInstruction(element, __('Please type the correct response in the box below.'));
    if (attributes.baseType === 'float') {
      $correctInput.attr('placeholder', __("example: 999".concat(decimalSeparator, "99")));
      if (correctResponse && !String(correctResponse).includes('.')) {
        correctResponse = "".concat(correctResponse, ".0");
      }
    }
    if (attributes.baseType === 'float' && decimalSeparator !== '.') {
      $correctInput.focus().val(correctResponse.replace('.', decimalSeparator));
    } else {
      $correctInput.focus().val(correctResponse);
    }
    $responseForm.on('change', '#responseBaseType', function () {
      if ($(this).val() === 'float') {
        $correctInput.attr('placeholder', __("example: 999".concat(decimalSeparator, "99")));
      } else {
        $correctInput.removeAttr('placeholder');
      }
      $correctInput.val('');
      stringResponseHelper.setCorrectResponse(response, '', {
        trim: true
      });
    });
    $container.on('blur.correct', 'tr[data-edit=correct] input[name=correct]', function () {
      $submitButton.attr('disabled', false);
      instructionMgr.removeInstructions(element);
      instructionMgr.appendInstruction(element, __('Please type the correct response in the box below.'));
      var $input = $(this);
      var value = $input.val();
      var responseValue = '';
      var numericBase = attributes.base || 10;
      var convertedValue = converter.convert(value.trim());
      switch (attributes.baseType) {
        case 'integer':
          if (value === '') {
            break;
          }
          value = locale.parseInt(convertedValue, numericBase);
          responseValue = isNaN(value) ? '' : value;
          if (!/^[+-]?[0-9]+(e-?\d*)?$/.test(convertedValue)) {
            widget.isValid(widget.serial, false, __('Invalid value in correct response property.'));
            return setErrorNotification($submitButton, element, attributes.baseType);
          }
          break;
        case 'float':
          if (value === '') {
            break;
          }
          value = locale.parseFloat(convertedValue);
          responseValue = isNaN(value) ? '' : value;
          var regex = new RegExp("^[+-]?[0-9]+\\".concat(decimalSeparator, "[0-9]+(e-?\\d*)?$"));
          if (value !== '' && !regex.test(convertedValue)) {
            widget.isValid(widget.serial, false, __('Invalid value in correct response property.'));
            return setErrorNotification($submitButton, element, "value is a decimal number as example: 999".concat(decimalSeparator, "99"));
          }
          break;
        case 'string':
          responseValue = convertedValue;
          break;
        default:
          return false;
      }
      widget.isValid(widget.serial, true);
      stringResponseHelper.setCorrectResponse(response, "".concat(responseValue), {
        trim: true
      });
    });
  }
  function exit() {
    var widget = this.widget;
    var response = widget.element.getResponseDeclaration();
    if (response.template === "no_response_processing") {
      widget.$container.find('button.widget-ok').attr('disabled', false);
      widget.isValid(widget.serial, true);
    }
    stringResponseHelper.rewriteCorrectResponse(response, {
      trim: true
    });
    widget.$container.off('.correct');
    instructionMgr.removeInstructions(widget.element);
  }
  return stateFactory.create(Correct, start, exit);
});
