define('taoQtiItem/qtiCreator/plugins/panel/outcomeEditor',['jquery', 'lodash', 'i18n', 'core/plugin', 'taoQtiItem/qtiItem/core/Element', 'taoQtiItem/qtiCreator/helper/popup', 'taoQtiItem/qtiCreator/widgets/helpers/formElement', 'taoQtiItem/qtiCreator/model/variables/OutcomeDeclaration', 'taoQtiItem/qtiCreator/helper/xmlRenderer', 'ui/tooltip', 'services/features', 'tpl!taoQtiItem/qtiCreator/tpl/outcomeEditor/panel', 'tpl!taoQtiItem/qtiCreator/tpl/outcomeEditor/listing'], function ($, _, __, pluginFactory, Element, popup, formElement, OutcomeDeclaration, xmlRenderer, tooltip, features, panelTpl, listingTpl) {
  'use strict';

  var _ns = '.outcome-editor';
  var externalScoredOptions = {
    none: 'none',
    human: 'human',
    externalMachine: 'externalMachine'
  };
  var externalScoredValidOptions = [externalScoredOptions.human, externalScoredOptions.externalMachine];
  function getRpUsedVariables(item) {
    var rpXml = xmlRenderer.render(item.responseProcessing);
    var variables = ['MAXSCORE'];
    var $rp = $(rpXml);
    $rp.find('variable,setOutcomeValue').each(function () {
      var id = $(this).attr('identifier');
      if (id !== 'SCORE') {
        variables.push(id);
      }
    });
    return _.uniq(variables);
  }
  function renderListing(item, $outcomeEditorPanel) {
    var readOnlyRpVariables = getRpUsedVariables(item);
    var scoreMaxScoreVisible = features.isVisible('taoQtiItem/creator/interaction/response/outcomeDeclarations/scoreMaxScore');
    var scoreExternalScored = _.get(_.find(item.outcomes, function (outcome) {
      return outcome.attributes && outcome.attributes.identifier === 'SCORE';
    }), 'attributes.externalScored', externalScoredOptions.none);
    var outcomesData = _.map(item.outcomes, function (outcome) {
      var readonly = readOnlyRpVariables.indexOf(outcome.id()) >= 0;
      var id = outcome.id();
      var externalScoredDisabled = outcome.attr('externalScoredDisabled');
      var externalScored = {
        none: {
          label: __('None'),
          selected: !outcome.attr('externalScored')
        },
        human: {
          label: __('Human'),
          selected: outcome.attr('externalScored') === externalScoredOptions.human
        },
        externalMachine: {
          label: __('External Machine'),
          selected: outcome.attr('externalScored') === externalScoredOptions.externalMachine
        }
      };
      function setExternalScoredToNone() {
        externalScoredDisabled = 1;
        outcome.removeAttr('externalScored');
      }
      function hasExternalScoredOutcome(outcomes) {
        return _.some(outcomes, function (outcome) {
          return outcome.attributes && outcome.attributes.identifier !== 'SCORE' && outcome.attributes.externalScored && outcome.attributes.externalScored !== externalScoredOptions.none;
        });
      }
      function shouldSetExternalScoredToNone() {
        if (id !== 'SCORE') {
          return scoreExternalScored && scoreExternalScored !== externalScoredOptions.none;
        }
        return hasExternalScoredOutcome(item.outcomes);
      }
      if (shouldSetExternalScoredToNone()) {
        setExternalScoredToNone();
      }
      return {
        serial: outcome.serial,
        identifier: id,
        hidden: (id === 'SCORE' || id === 'MAXSCORE') && !scoreMaxScoreVisible,
        interpretation: outcome.attr('interpretation'),
        longInterpretation: outcome.attr('longInterpretation'),
        externalScored: externalScored,
        normalMaximum: outcome.attr('normalMaximum'),
        normalMinimum: outcome.attr('normalMinimum'),
        titleDelete: readonly ? __('Cannot delete a variable currently used in response processing') : __('Delete'),
        titleEdit: readonly ? __('Cannot edit a variable currently used in response processing') : __('Edit'),
        readonly: readonly,
        externalScoredDisabled: externalScoredDisabled || 0
      };
    });
    var allExternalScoredDisabled = outcomesData.every(outcomeData => outcomeData.externalScoredDisabled === 1);
    if (allExternalScoredDisabled) {
      outcomesData.forEach(outcomeData => outcomeData.externalScoredDisabled = 0);
    }
    $outcomeEditorPanel.find('.outcomes').html(listingTpl({
      outcomes: outcomesData
    }));
    formElement.initWidget($outcomeEditorPanel);
  }
  function isValidScoringTrait(value) {
    return value % 1 === 0 && typeof value !== 'undefined';
  }
  var attachScoringTraitWarningTooltip = $field => {
    var widgetTooltip;
    if (!$field.data('$tooltip')) {
      widgetTooltip = tooltip.warning($field, __("This value does not follow scoring traits guidelines. It won't be compatible with TAO Manual Scoring"), {
        trigger: 'manual',
        placement: 'left-start'
      });
      $field.data('$tooltip', widgetTooltip);
    }
  };
  function setMinumumMaximumValue(outcomeElement, outcomeValueContainer, min, max) {
    outcomeElement.attr('normalMaximum', max);
    outcomeValueContainer.find('[name="normalMaximum"]').val(max);
    outcomeElement.attr('normalMinimum', min);
    outcomeValueContainer.find('[name="normalMinimum"]').val(min);
  }
  function updateExternalScored(responsePanel, serial, disableCondition, shouldDisable) {
    responsePanel.find('.outcome-container').each(function () {
      var currentSerial = $(this).data('serial');
      if (currentSerial === serial) {
        return;
      }
      var currentOutcomeElement = Element.getElementBySerial(currentSerial);
      var id = $(this).find(".identifier").val();
      if (disableCondition(id)) {
        $(this).find("select[name='externalScored']").attr('disabled', shouldDisable);
        if (shouldDisable) {
          currentOutcomeElement.removeAttr('externalScored');
        }
      }
    });
  }
  function shouldDisableScoreBasedOnOtherVariables(responsePanel, serial) {
    var shouldDisable = false;
    responsePanel.find('.outcome-container').each(function () {
      var currentSerial = $(this).data('serial');
      var id = $(this).find(".identifier").val();
      if (currentSerial === serial || id === 'SCORE') {
        return;
      }
      var currentValue = $(this).find("select[name='externalScored']").val();
      if (currentValue !== externalScoredOptions.none) {
        shouldDisable = true;
        return false;
      }
    });
    return shouldDisable;
  }
  var removeScoringTraitWarningTooltip = $field => {
    if ($field.data('$tooltip')) {
      $field.data('$tooltip').dispose();
      $field.removeData('$tooltip');
    }
  };
  return pluginFactory({
    name: 'outcomeEditor',
    init: function init() {
      var item = this.getHost().getItem();
      var $container = this.getAreaBroker().getContainer();
      var $responsePanel = $container.find('#sidebar-right-response-properties');
      var $outcomeEditorPanel;
      $container.on("initResponseForm".concat(_ns), function () {
        $responsePanel.find('.qti-outcome-editor').remove();
        $outcomeEditorPanel = $(panelTpl());
        $outcomeEditorPanel.on("click".concat(_ns), '.editable [data-role="edit"]', function () {
          var $outcomeContainer = $(this).closest('.outcome-container');
          var serial = $outcomeContainer.data('serial');
          var outcomeElement = Element.getElementBySerial(serial);
          var $labelContainer = $outcomeContainer.find('.identifier-label');
          var $incrementerContainer = $outcomeContainer.find(".incrementer");
          var $identifierLabel = $labelContainer.find('.label');
          var $identifierInput = $labelContainer.find('.identifier');
          var $outcomeValueContainer = $outcomeContainer.find('div.minimum-maximum');
          var isScoreOutcome = outcomeElement.attributes.identifier === 'SCORE';
          var isScoringTraitValidationEnabled = outcomeElement.attr('externalScored') === externalScoredOptions.human;
          if (!externalScoredValidOptions.includes(outcomeElement.attr("externalScored"))) {
            $incrementerContainer.incrementer("disable");
            setMinumumMaximumValue(outcomeElement, $outcomeValueContainer, 0, 0);
          } else {
            $incrementerContainer.incrementer("enable");
          }
          $outcomeContainer.addClass('editing');
          $outcomeContainer.removeClass('editable');
          $identifierInput.focus();
          $identifierInput.val('');
          $identifierInput.val(outcomeElement.id());
          var showScoringTraitWarningOnInvalidValue = () => {
            if (!isValidScoringTrait(outcomeElement.attr('normalMinimum')) || !isValidScoringTrait(outcomeElement.attr('normalMaximum'))) {
              $outcomeValueContainer.data('$tooltip').show();
            } else {
              $outcomeValueContainer.data('$tooltip').hide();
            }
          };
          if (isScoringTraitValidationEnabled) {
            attachScoringTraitWarningTooltip($outcomeValueContainer);
            showScoringTraitWarningOnInvalidValue();
          }
          formElement.setChangeCallbacks($outcomeContainer, outcomeElement, _.assign({
            identifier(outcome, value) {
              $identifierLabel.html(value);
              outcome.id(value);
            },
            interpretation(outcome, value) {
              $labelContainer.attr('title', value);
              outcome.attr('interpretation', value);
            },
            longInterpretation(outcome, value) {
              $labelContainer.attr('title', value);
              outcome.attr('longInterpretation', value);
            },
            externalScored(outcome, value) {
              isScoringTraitValidationEnabled = value === externalScoredOptions.human;
              if (isScoreOutcome && value !== externalScoredOptions.none) {
                $incrementerContainer.incrementer("enable");
              } else if (isScoreOutcome) {
                setMinumumMaximumValue(outcome, $outcomeValueContainer, 0, 0);
                $incrementerContainer.incrementer("disable");
              } else if (value !== externalScoredOptions.none) {
                $incrementerContainer.incrementer("enable");
              } else {
                setMinumumMaximumValue(outcome, $outcomeValueContainer, 0, 0);
                $incrementerContainer.incrementer("disable");
              }
              if (value === externalScoredOptions.human) {
                attachScoringTraitWarningTooltip($outcomeValueContainer);
                showScoringTraitWarningOnInvalidValue();
              } else {
                removeScoringTraitWarningTooltip($outcomeValueContainer);
              }
              if (value === externalScoredOptions.none) {
                outcome.removeAttr('externalScored');
              } else {
                outcome.attr('externalScored', value);
              }
              if (isScoreOutcome && value !== externalScoredOptions.none) {
                updateExternalScored($responsePanel, serial, function (id) {
                  return value !== externalScoredOptions.none;
                }, true);
              } else if (isScoreOutcome && value === externalScoredOptions.none) {
                updateExternalScored($responsePanel, serial, function (id) {
                  return id !== 'SCORE';
                }, false);
              } else if (value !== externalScoredOptions.none) {
                updateExternalScored($responsePanel, serial, function (id) {
                  return id === 'SCORE';
                }, true);
              } else {
                var shouldDisable = shouldDisableScoreBasedOnOtherVariables($responsePanel, serial);
                updateExternalScored($responsePanel, serial, function (id) {
                  return id === 'SCORE';
                }, shouldDisable);
              }
            }
          }, formElement.getMinMaxAttributeCallbacks('normalMinimum', 'normalMaximum', {
            allowNull: true,
            floatVal: true,
            callback: function callback(outcome, value, attr) {
              if (isScoringTraitValidationEnabled) {
                showScoringTraitWarningOnInvalidValue();
              }
              if (isNaN(value)) {
                outcome.removeAttr(attr);
              } else {
                value = Math.round(value);
                outcome.attr(attr, value);
                $outcomeValueContainer.find("[name = \"".concat(attr, "\"]")).val(value);
                if (attr === 'normalMinimum' && outcome.attr('normalMaximum') < value) {
                  outcome.attr('normalMaximum', value);
                  $outcomeValueContainer.find('[name="normalMaximum"]').val(value);
                } else if (attr === 'normalMaximum' && outcome.attr('normalMinimum') > value) {
                  outcome.attr('normalMinimum', value);
                  $outcomeValueContainer.find('[name="normalMinimum"]').val(value);
                }
              }
            }
          })), {
            saveInvalid: true,
            validateOnInit: true
          });
        }).on("click".concat(_ns), '.editing [data-role="edit"]', function () {
          var $outcomeContainer = $(this).closest('.outcome-container');
          $outcomeContainer.removeClass('editing');
          $outcomeContainer.addClass('editable');
          formElement.removeChangeCallback($outcomeContainer);
        }).on("click".concat(_ns), '.deletable [data-role="delete"]', function () {
          var $outcomeContainer = $(this).closest('.outcome-container');
          var serial = $outcomeContainer.data('serial');
          var shouldDisable = shouldDisableScoreBasedOnOtherVariables($responsePanel, serial);
          updateExternalScored($responsePanel, serial, function (id) {
            return id === 'SCORE';
          }, shouldDisable);
          $outcomeContainer.remove();
          item.remove('outcomes', $outcomeContainer.data('serial'));
        }).on("click".concat(_ns), '.adder', function (e) {
          e.preventDefault();
          var newOutcome = new OutcomeDeclaration({
            cardinality: 'single',
            baseType: 'float',
            normalMinimum: 0.0,
            normalMaximum: 1.0
          });
          item.addOutcomeDeclaration(newOutcome);
          newOutcome.buildIdentifier('OUTCOME');
          renderListing(item, $outcomeEditorPanel);
        });
        $responsePanel.append($outcomeEditorPanel);
        renderListing(item, $outcomeEditorPanel);
      });
    }
  });
});
