define('taoQtiItem/qtiCreator/editor/styleEditor/fontSelector',['jquery', 'lodash', 'json!taoQtiItem/qtiCreator/editor/resources/font-stacks.json', 'taoQtiItem/qtiCreator/editor/styleEditor/styleEditor', 'i18n', 'select2'], function ($, _, fontStacks, styleEditor, __) {
  'use strict';
  function fontSelector() {
    var selector = 'select#item-editor-font-selector',
      $selector = $(selector),
      target = $selector.data('target'),
      cssVariablesRootSelector = styleEditor.getConfig().cssVariablesRootSelector,
      normalize = function normalize(font) {
        return font.replace(/"/g, "'").replace(/, /g, ',');
      },
      clean = function clean(font) {
        return font.substring(0, font.indexOf(',')).replace(/'/g, '');
      },
      resetButton = $selector.parent().find('[data-role="font-selector-reset"]'),
      toLabel = function toLabel(font) {
        font = font.replace(/-/g, ' ');
        return "".concat(font).replace(/^([a-z\u00E0-\u00FC])|\s+([a-z\u00E0-\u00FC])/g, function ($1) {
          return $1.toUpperCase();
        });
      },
      format = function format(state) {
        var originalOption = state.element;
        if (!state.id) {
          return state.text;
        }
        return "<span style=\"font-size: 12px;".concat($(originalOption).attr('style'), "\">").concat(state.text, "</span>");
      },
      styleEditorApply = function styleEditorApply(val) {
        var varName = '--styleeditor-font-family';
        styleEditor.apply(cssVariablesRootSelector, varName, val);
        styleEditor.apply(target, 'font-family', val ? "var(".concat(varName, ")") : null);
      };
    $selector.append("<option value=\"\">".concat(__('Default'), "</option>"));
    _.forEach(fontStacks, (value, key) => {
      var optGroup = $('<optgroup>', {
        label: toLabel(key)
      });
      _.forEach(value, font => {
        var normalizeFont = normalize(font);
        var option = $('<option>', {
          value: normalizeFont,
          text: clean(normalizeFont)
        }).css({
          fontFamily: normalizeFont
        });
        optGroup.append(option);
      });
      $selector.append(optGroup);
    });
    resetButton.on('click', function () {
      styleEditorApply(null);
      $selector.select2('val', '');
    });
    $selector.select2({
      formatResult: format,
      formatSelection: format,
      width: 'resolve'
    });
    $(document).on('customcssloaded.styleeditor', function (e, style) {
      var shouldFireStyleChange = false;
      var val = style[cssVariablesRootSelector] && style[cssVariablesRootSelector]['--styleeditor-font-family'];
      if (!val) {
        val = style[target] && style[target]['font-family'];
        shouldFireStyleChange = true;
      }
      if (val) {
        $selector.select2('val', val);
        $("".concat(selector, " option:selected")).first().attr('selected', 'selected');
        if (shouldFireStyleChange) {
          styleEditorApply(val);
        }
      }
    });
    $selector.on('change', function () {
      styleEditorApply($(this).val());
      $("".concat(selector, " option:selected")).first().attr('selected', 'selected');
    });
  }
  return fontSelector;
});
