define('taoQtiItem/qtiCreator/widgets/static/helpers/inline',['lodash', 'taoQtiItem/qtiCreator/helper/dummyElement', 'ui/validator/validators'], function (_, dummyElement, validators) {
  var _qtiClassToDummies = {
    math: 'maths',
    img: 'image',
    object: 'media'
  };
  var inlineHelper = {
    checkFileExists: function checkFileExists(widget, element, fileSrcAttrName, baseUrl) {
      validators.validators.fileExists.validate(element.attr(fileSrcAttrName), function (fileExists) {
        if (!fileExists) {
          element.attr(fileSrcAttrName, '');
          inlineHelper.togglePlaceholder(widget);
        }
      }, {
        baseUrl: baseUrl || ''
      });
    },
    togglePlaceholder: function togglePlaceholder(widget, opts) {
      var options = _.defaults(opts || {}, {
        container: widget.$original,
        type: widget.element.qtiClass
      });
      var $container = options.container;
      var $placeholder = $container.siblings('.dummy-element');
      if (widget.element.isEmpty()) {
        $container.hide();
        var type = _qtiClassToDummies[options.type] || options.type;
        if (!$placeholder.length) {
          $placeholder = dummyElement.get(type);
          $container.after($placeholder);
        }
        $placeholder.show();
      } else {
        $container.show();
        $placeholder.hide();
      }
      widget.$container.trigger('contentChange.qti-widget');
    },
    positionFloat: function positionFloat(widget, position) {
      var $container = widget.$container,
        elt = widget.element;
      $container.removeClass('rgt lft');
      elt.removeClass('rgt');
      elt.removeClass('lft');
      switch (position) {
        case 'right':
          $container.addClass('rgt');
          elt.addClass('rgt');
          break;
        case 'left':
          $container.addClass('lft');
          elt.addClass('lft');
          break;
      }
    }
  };
  return inlineHelper;
});
